    lat: 11.3168,
    lng: 106.0965,
    openHours: '07:30 - 17:00',
    phone: '02763888888',
    priceLevel: 'bình dân',
    rating: 4.9,
    amenities: ['parking', 'aircon', 'wifi'],
    imageUrl: '',
    description: 'Tiếp nhận và giải quyết thủ tục hành chính một cửa cấp tỉnh, hỗ trợ dịch vụ công trực tuyến nhanh chóng.',
    status: 'approved'
  },
  {
    id: 'seed-8',
    name: 'Tổng Đài Cấp Cứu & Đường Dây Nóng Khẩn Cấp 113 - 114 - 115',
    category: 'Hành chính công',
    subCategory: 'Số điện thoại đường dây nóng',
    address: 'Toàn tỉnh Tây Ninh',
    lat: 11.3117,
    lng: 106.0988,
    openHours: '24/7',
    phone: '115',
    priceLevel: 'bình dân',
    rating: 5.0,
    amenities: [],
    imageUrl: '',
    description: 'Đường dây nóng khẩn cấp: 113 (Công an an ninh), 114 (Cứu hỏa PCCC), 115 (Cấp cứu y tế). Trực 24/24 tiếp nhận phản ánh.',
    status: 'approved'
  }
