createApp({
  setup() {
    const isDark = ref(localStorage.getItem('tayninh_dark') === 'true');
    const viewMode = ref('split'); // 'split' | 'grid'
    const loading = ref(true);
    const toasts = ref([]);
    const currentUser = ref(null);
    const userMenuOpen = ref(false);

    // Geolocation người dùng
    const userCoords = ref(null);
    const isLocating = ref(false);

    // Danh sách địa điểm
    const places = ref([]);
    const selectedPlace = ref(null);
    const activePlaceDetail = ref(null);
    const activePlaceReviews = ref([]);

    // Bộ lọc
    const searchKeyword = ref('');
    const activeCategory = ref('all');
    const activeSubcategory = ref('');
    const filterOpenNow = ref('all');
    const filterDistance = ref('all');
    const filterPrice = ref('all');
    const selectedAmenities = ref([]);

    // Form đóng góp địa điểm
    const showContributeModal = ref(false);
    const submittingPlace = ref(false);
    const newPlaceForm = ref({
      name: '',
      category: 'Ẩm thực và Giải trí',
      subCategory: 'Quán ăn đặc sản',
      address: '',
      lat: DEFAULT_LAT,
      lng: DEFAULT_LNG,
      openHours: '07:00 - 22:00',
      phone: '',
      priceLevel: 'bình dân',
      imageUrl: '',
      amenities: ['parking', 'card'],
      description: ''
    });

    // Form đánh giá
    const newReviewRating = ref(5);
    const newReviewComment = ref('');
    const submittingReview = ref(false);

    // Danh mục tiện ích
    const availableAmenities = [
      { key: 'parking', label: 'Chỗ đậu ô tô', icon: 'fa-solid fa-square-parking' },
      { key: 'card', label: 'Thanh toán thẻ/QR', icon: 'fa-solid fa-credit-card' },
      { key: 'aircon', label: 'Phòng máy lạnh', icon: 'fa-solid fa-snowflake' },
      { key: 'wifi', label: 'Wifi miễn phí', icon: 'fa-solid fa-wifi' },
      { key: 'delivery', label: 'Giao hàng tận nơi', icon: 'fa-solid fa-motorcycle' }
    ];

    // Leaflet Map instance
    let mapInstance = null;
    let markersGroup = null;
    let userMarker = null;

    // Tính khoảng cách Haversine (km)
    const calculateDistance = (lat1, lon1, lat2, lon2) => {
      const R = 6371; // km
      const dLat = (lat2 - lat1) * Math.PI / 180;
      const dLon = (lon2 - lon1) * Math.PI / 180;
      const a = 
        Math.sin(dLat/2) * Math.sin(dLat/2) +
        Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
        Math.sin(dLon/2) * Math.sin(dLon/2);
      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
      return Math.round(R * c * 10) / 10;
    };

    // Lấy danh mục con tương ứng
    const currentSubcategories = computed(() => {
      if (activeCategory.value === 'Ẩm thực và Giải trí') {
        return ['Quán cà phê', 'Quán ăn đặc sản', 'Nhà hàng', 'Điểm check-in du lịch'];
      }
      if (activeCategory.value === 'Dịch vụ thiết yếu') {
        return ['Sửa xe', 'Y tế (bệnh viện / nhà thuốc)', 'Ngân hàng & ATM', 'Trạm xăng', 'Dịch vụ công nghệ'];
      }
      if (activeCategory.value === 'Hành chính công') {
        return ['Danh bạ cơ quan nhà nước', 'Số điện thoại đường dây nóng', 'Thủ tục hành chính nhanh'];
      }
      return ['Đặc sản', 'Du lịch', 'Cứu hộ 24/7', 'Y tế', 'Hành chính'];
    });

    // Kiểm tra đang mở cửa
    const isOpenNow = (hoursStr) => {
      if (!hoursStr) return true;
      if (hoursStr.includes('24/7') || hoursStr.includes('24/24')) return true;
      const parts = hoursStr.split('-');
      if (parts.length !== 2) return true;
      const now = new Date();
      const curMinutes = now.getHours() * 60 + now.getMinutes();

      const parseMin = (s) => {
        const p = s.trim().split(':');
        return parseInt(p[0]) * 60 + (p[1] ? parseInt(p[1]) : 0);
      };
      const start = parseMin(parts[0]);
      const end = parseMin(parts[1]);
      return curMinutes >= start && curMinutes <= end;
    };

    // Danh sách địa điểm đã lọc
    const filteredPlaces = computed(() => {
      return places.value.filter(p => {
        // Danh mục chính
        if (activeCategory.value !== 'all' && p.category !== activeCategory.value) {
          return false;
        }
        // Danh mục con
        if (activeSubcategory.value && p.subCategory !== activeSubcategory.value && !p.subCategory?.includes(activeSubcategory.value)) {
          return false;
        }
        // Tìm kiếm
        if (searchKeyword.value) {
          const kw = searchKeyword.value.toLowerCase();
          const matchName = p.name.toLowerCase().includes(kw);
          const matchAddr = p.address && p.address.toLowerCase().includes(kw);
          const matchSub = p.subCategory && p.subCategory.toLowerCase().includes(kw);
          if (!matchName && !matchAddr && !matchSub) return false;
        }
        // Trạng thái mở cửa
        if (filterOpenNow.value === 'open' && !isOpenNow(p.openHours)) {
          return false;
        }
        // Mức giá
        if (filterPrice.value !== 'all' && p.priceLevel !== filterPrice.value) {
          return false;
        }
        // Khoảng cách
        if (filterDistance.value !== 'all' && p.distanceKm !== undefined) {
          if (p.distanceKm > parseFloat(filterDistance.value)) return false;
        }
        // Tiện ích
        if (selectedAmenities.value.length > 0) {
          const pAmenities = p.amenities || [];
          const matchAll = selectedAmenities.value.every(am => pAmenities.includes(am));
          if (!matchAll) return false;
        }
        return true;
      }).sort((a, b) => {
        // Sắp xếp ưu tiên theo khoảng cách nếu đã có GPS
        if (a.distanceKm !== undefined && b.distanceKm !== undefined) {
          return a.distanceKm - b.distanceKm;
        }
        return (b.rating || 5) - (a.rating || 5);
      });
    });

    const hasActiveFilters = computed(() => {
      return activeCategory.value !== 'all' || 
             activeSubcategory.value !== '' || 
             searchKeyword.value !== '' || 
             filterOpenNow.value !== 'all' || 
             filterDistance.value !== 'all' || 
             filterPrice.value !== 'all' || 
             selectedAmenities.value.length > 0;
    });

    const resetFilters = () => {
      activeCategory.value = 'all';
      activeSubcategory.value = '';
      searchKeyword.value = '';
      filterOpenNow.value = 'all';
      filterDistance.value = 'all';
      filterPrice.value = 'all';
      selectedAmenities.value = [];
    };

    const toggleAmenityFilter = (key) => {
      const idx = selectedAmenities.value.indexOf(key);
      if (idx > -1) selectedAmenities.value.splice(idx, 1);
      else selectedAmenities.value.push(key);
    };

    const getAmenityLabel = (key) => {
      const item = availableAmenities.find(a => a.key === key);
      return item ? item.label : key;
    };

    const getCategoryBadgeClass = (cat) => {
      if (cat === 'Ẩm thực và Giải trí') return 'bg-rose-100 text-rose-700 dark:bg-rose-950/60 dark:text-rose-300';
      if (cat === 'Dịch vụ thiết yếu') return 'bg-blue-100 text-blue-700 dark:bg-blue-950/60 dark:text-blue-300';
      return 'bg-amber-100 text-amber-700 dark:bg-amber-950/60 dark:text-amber-300';
    };

    const selectMainCategory = (cat) => {
      activeCategory.value = cat;
      activeSubcategory.value = '';
    };

    // Khởi tạo bản đồ Leaflet
    const initMap = () => {
      const mapEl = document.getElementById('directoryMap');
      if (!mapEl) return;

      mapInstance = L.map('directoryMap', { zoomControl: false }).setView([DEFAULT_LAT, DEFAULT_LNG], 12);
      L.control.zoom({ position: 'topright' }).addTo(mapInstance);

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
        attribution: '&copy; OpenStreetMap | Tây Ninh Go'
      }).addTo(mapInstance);

      markersGroup = L.layerGroup().addTo(mapInstance);

      // Click trên bản đồ để lấy tọa độ vào form đóng góp
      mapInstance.on('click', (e) => {
        newPlaceForm.value.lat = parseFloat(e.latlng.lat.toFixed(6));
        newPlaceForm.value.lng = parseFloat(e.latlng.lng.toFixed(6));
        showToast(`Đã chọn tọa độ: ${newPlaceForm.value.lat}, ${newPlaceForm.value.lng}`);
      });

      renderMarkers();
    };

    // Render markers lên bản đồ
    const renderMarkers = () => {
      if (!markersGroup || !mapInstance) return;
      markersGroup.clearLayers();

      filteredPlaces.value.forEach(place => {
        if (!place.lat || !place.lng) return;

        // Marker icon màu sắc theo category
        let color = '#059669';
        if (place.category === 'Ẩm thực và Giải trí') color = '#e11d48';
        if (place.category === 'Dịch vụ thiết yếu') color = '#2563eb';
        if (place.category === 'Hành chính công') color = '#d97706';

        const customIcon = L.divIcon({
          className: 'custom-map-marker',
          html: `<div style="background-color:${color};width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;box-shadow:0 3px 8px rgba(0,0,0,0.3);border:2px solid #fff;"><i class="fa-solid fa-location-dot" style="font-size:13px;"></i></div>`,
          iconSize: [28, 28],
          iconAnchor: [14, 28]
        });

        const marker = L.marker([place.lat, place.lng], { icon: customIcon });

        const popupContent = `
          <div style="font-family:sans-serif;padding:6px;min-width:200px;">
            <span style="font-size:10px;font-weight:bold;padding:2px 6px;border-radius:4px;background:#e0f2fe;color:#0369a1;">${place.category}</span>
            <h4 style="margin:4px 0 2px 0;font-size:14px;color:#1e293b;">${place.name}</h4>
            <p style="margin:0 0 6px 0;font-size:11px;color:#64748b;">${place.address}</p>
            <div style="display:flex;justify-content:space-between;align-items:center;border-top:1px solid #f1f5f9;padding-top:6px;">
              <span style="color:#d97706;font-weight:bold;font-size:11px;">⭐ ${(place.rating || 5.0).toFixed(1)}</span>
              <a href="https://www.google.com/maps?q=${place.lat},${place.lng}" target="_blank" style="color:#059669;font-weight:bold;font-size:11px;text-decoration:none;">🗺️ Chỉ đường</a>
            </div>
          </div>
        `;
        marker.bindPopup(popupContent);
        markersGroup.addLayer(marker);
      });
    };

    // Chọn place từ card
    const selectPlace = (place) => {
      selectedPlace.value = place;
      if (mapInstance && place.lat && place.lng) {
        mapInstance.flyTo([place.lat, place.lng], 16, { duration: 0.8 });
      }
    };

    // Mở modal chi tiết & tải đánh giá
    const openDetailModal = async (place) => {
      activePlaceDetail.value = place;
      activePlaceReviews.value = [];
      try {
        const q = query(
          collection(db, 'place_reviews'), 
          where('placeId', '==', place.id),
          limit(20)
        );
        const snapshot = await getDocs(q);
        activePlaceReviews.value = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      } catch (e) {
        console.warn('Reviews fallback:', e);
      }
    };

    // Gửi đánh giá cho địa điểm
    const submitReview = async () => {
      if (!activePlaceDetail.value) return;
      submittingReview.value = true;
      try {
        const reviewData = {
          placeId: activePlaceDetail.value.id,
          authorName: currentUser.value ? currentUser.value.displayName : 'Cộng đồng Tây Ninh',
          authorId: currentUser.value ? currentUser.value.uid : 'anon',
          rating: newReviewRating.value,
          comment: newReviewComment.value.trim(),
          createdAt: serverTimestamp(),
          timeAgo: 'Vừa xong'
        };

        await addDoc(collection(db, 'place_reviews'), reviewData);
        activePlaceReviews.value.unshift(reviewData);

        // Cập nhật rating trung bình
        const totalRating = activePlaceReviews.value.reduce((acc, r) => acc + (r.rating || 5), 0);
        activePlaceDetail.value.rating = Math.round((totalRating / activePlaceReviews.value.length) * 10) / 10;

        newReviewComment.value = '';
        showToast('Cảm ơn bạn! Đánh giá đã được ghi nhận.');
      } catch (err) {
        console.error('Error submitting review:', err);
        showToast('Lỗi gửi đánh giá, vui lòng thử lại.');
      } finally {
        submittingReview.value = false;
      }
    };

    // Vị trí người dùng (GPS Geolocation)
    const getUserLocation = () => {
      if (!navigator.geolocation) {
        showToast('Trình duyệt không hỗ trợ định vị GPS.');
        return;
      }
      isLocating.value = true;
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          isLocating.value = false;
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          userCoords.value = { lat, lng };

          // Tính lại khoảng cách cho tất cả các địa điểm
          places.value.forEach(p => {
            if (p.lat && p.lng) {
              p.distanceKm = calculateDistance(lat, lng, p.lat, p.lng);
            }
          });

          if (mapInstance) {
            mapInstance.flyTo([lat, lng], 14, { duration: 1 });
            if (userMarker) mapInstance.removeLayer(userMarker);

            const userIcon = L.divIcon({
              className: 'user-location-marker',
              html: '<div style="background-color:#0284c7;width:20px;height:20px;border-radius:50%;border:3px solid #fff;box-shadow:0 0 10px rgba(2,132,199,0.8);animation:pulse 2s infinite;"></div>',
              iconSize: [20, 20],
              iconAnchor: [10, 10]
            });
            userMarker = L.marker([lat, lng], { icon: userIcon }).addTo(mapInstance)
              .bindPopup('<b>Vị trí của bạn</b>')
              .openPopup();
          }
          showToast('Đã xác định vị trí của bạn!');
        },
        (err) => {
          isLocating.value = false;
          showToast('Không thể lấy vị trí. Vui lòng cấp quyền GPS.');
        },
        { enableHighAccuracy: true, timeout: 8000 }
      );
    };

    const resetMapView = () => {
      if (mapInstance) {
        mapInstance.flyTo([DEFAULT_LAT, DEFAULT_LNG], 12, { duration: 0.8 });
      }
    };

    // Mở Modal Đóng góp địa điểm
    const openContributeModal = () => {
      if (userCoords.value) {
        newPlaceForm.value.lat = userCoords.value.lat;
        newPlaceForm.value.lng = userCoords.value.lng;
      }
      showContributeModal.value = true;
    };

    // Gửi đóng góp địa điểm mới lên Firestore
    const submitNewPlace = async () => {
      submittingPlace.value = true;
      try {
        const payload = {
          name: newPlaceForm.value.name.trim(),
          category: newPlaceForm.value.category,
          subCategory: newPlaceForm.value.subCategory.trim(),
          address: newPlaceForm.value.address.trim(),
          lat: parseFloat(newPlaceForm.value.lat),
          lng: parseFloat(newPlaceForm.value.lng),
          openHours: newPlaceForm.value.openHours.trim(),
          phone: newPlaceForm.value.phone.trim(),
          priceLevel: newPlaceForm.value.priceLevel,
          imageUrl: newPlaceForm.value.imageUrl.trim(),
          amenities: newPlaceForm.value.amenities,
          description: newPlaceForm.value.description.trim(),
          rating: 5.0,
          status: 'pending', // Chờ kiểm duyệt
          authorId: currentUser.value ? currentUser.value.uid : 'anon',
          createdAt: serverTimestamp()
        };

        await addDoc(collection(db, 'places'), payload);

        showToast('Đóng góp thành công! Địa điểm sẽ hiển thị ngay sau khi duyệt.');
        showContributeModal.value = false;
        // Reset form
        newPlaceForm.value.name = '';
        newPlaceForm.value.address = '';
        newPlaceForm.value.description = '';
      } catch (err) {
        console.error('Lỗi khi gửi đóng góp:', err);
        showToast('Lỗi gửi dữ liệu: ' + err.message);
      } finally {
        submittingPlace.value = false;
      }
    };

    // Tải danh sách địa điểm (Firestore + Seed Data)
    const loadPlaces = () => {
      loading.value = true;
      try {
        const q = query(collection(db, 'places'), where('status', '==', 'approved'));
        onSnapshot(q, (snapshot) => {
          const livePlaces = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
          // Hợp nhất dữ liệu mẫu & dữ liệu đám mây Firestore
          places.value = [...SEED_PLACES, ...livePlaces];
          loading.value = false;
          renderMarkers();
        }, (err) => {
          console.warn('Firestore places read error (using seed data):', err);
          places.value = SEED_PLACES;
          loading.value = false;
          renderMarkers();
        });
      } catch (e) {
        places.value = SEED_PLACES;
        loading.value = false;
        renderMarkers();
      }
    };

    // Auth
    const loginGoogle = async () => {
      try {
        const provider = new GoogleAuthProvider();
        const res = await signInWithPopup(auth, provider);
        currentUser.value = res.user;
        showToast(`Chào mừng ${res.user.displayName}!`);
      } catch (err) {
        console.error(err);
        // Chế độ demo
        currentUser.value = {
          displayName: 'Người Dùng Tây Ninh',
          email: 'ptquang0968@gmail.com',
          uid: 'demo_user'
        };
        showToast('Đã đăng nhập chế độ trải nghiệm.');
      }
    };

    const logout = async () => {
      await signOut(auth);
      currentUser.value = null;
      userMenuOpen.value = false;
      showToast('Đã đăng xuất.');
    };

    const toggleDarkMode = () => {
      isDark.value = !isDark.value;
      localStorage.setItem('tayninh_dark', isDark.value);
      if (isDark.value) document.documentElement.classList.add('dark');
      else document.documentElement.classList.remove('dark');
    };

    const showToast = (message) => {
      const id = Date.now();
      toasts.value.push({ id, message });
      setTimeout(() => {
        toasts.value = toasts.value.filter(t => t.id !== id);
      }, 4000);
    };

    // Watchers
    watch(filteredPlaces, () => {
      renderMarkers();
    });

    watch(viewMode, (newMode) => {
      if (newMode === 'split') {
        setTimeout(() => {
          if (mapInstance) mapInstance.invalidateSize();
        }, 300);
      }
    });

    onMounted(() => {
      if (isDark.value) document.documentElement.classList.add('dark');
      onAuthStateChanged(auth, (user) => {
        currentUser.value = user;
      });
      loadPlaces();
      setTimeout(() => {
        initMap();
      }, 200);
    });

    return {
      isDark,
      viewMode,
      loading,
      toasts,
      currentUser,
      userMenuOpen,
      userCoords,
      isLocating,
      places,
      selectedPlace,
      activePlaceDetail,
      activePlaceReviews,
      searchKeyword,
      activeCategory,
      activeSubcategory,
      currentSubcategories,
      filterOpenNow,
      filterDistance,
      filterPrice,
      selectedAmenities,
      availableAmenities,
      filteredPlaces,
      hasActiveFilters,
      showContributeModal,
      submittingPlace,
      newPlaceForm,
      newReviewRating,
      newReviewComment,
      submittingReview,
      selectMainCategory,
      toggleAmenityFilter,
      getAmenityLabel,
      getCategoryBadgeClass,
      isOpenNow,
      resetFilters,
      selectPlace,
      openDetailModal,
      submitReview,
      getUserLocation,
      resetMapView,
      openContributeModal,
      submitNewPlace,
      loginGoogle,
      logout,
      toggleDarkMode
    };
  }
}).mount('#app');
//
